for name,title,content in [('foundation','The foundation - Noklith',foundation),('product','Noklith, in motion',product)]:
    head=prefix.replace('<body>','<body class="cinematic-page">')
    head=re.sub(r'<title>.*?</title>',f'<title>{title}</title>',head)
    head=head.replace('<a class="active" href="/">HOME</a>','<a href="/">HOME</a>')
    head=head.replace(f'<a href="/{name}.html">',f'<a class="active" href="/{name}.html">',1)
    tail=suffix
    for part in ['about','slabs','how-it-works','field-notes','faq','home','chapters']:
        head=head.replace(f'href="#{part}"',f'href="/#{part}"')
        tail=tail.replace(f'href="#{part}"',f'href="/#{part}"')
    (root/'dist'/f'{name}.html').write_text(head+'<main id="main" class="page-main">'+content+'</main>\n'+tail)
